  attachPlayerLoadout(playerId: string, selection?: LoadoutSelection): void {
    // Frischer Ultimate-State (deaktiviert u. a. ein laufendes Armageddon nach Reconnect),
    // dann das Default-Loadout aus der eingefrorenen bzw. Live-Auswahl.
    this.systems.rocketMagazine?.cancel(playerId);
    this.systems.ultimateBehavior.resetPlayer(playerId);
    this.systems.ak47Behavior?.resetPlayer(playerId);
    this.systems.negevBehavior.resetPlayer(playerId);
    this.systems.sustainedWeaponBehavior.resetPlayer(playerId);
    this.systems.weaponReaction.resetPlayer(playerId);
    this.systems.molotovUpgrade?.removePlayer(playerId);
    this.systems.loadout.assignDefaultLoadout(playerId, selection);
    this.shieldBuffPort?.resetPlayer(playerId);
    this.systems.utilityAction.syncEquippedUtility(playerId);
  }

  detachPlayerLoadout(playerId: string): void {
    this.turretControl.release(playerId);
    this.systems.ultimateBehavior.removePlayer(playerId);
    this.systems.ak47Behavior?.removePlayer(playerId);
    this.systems.rocketMagazine?.removePlayer(playerId);
    this.systems.negevBehavior.removePlayer(playerId);
    this.systems.sustainedWeaponBehavior.removePlayer(playerId);
    this.systems.weaponReaction.removePlayer(playerId);
    this.systems.molotovUpgrade?.removePlayer(playerId);
    this.systems.utilityAction.removePlayer(playerId);
    this.systems.loadout.removePlayer(playerId);
    this.shieldBuffPort?.removePlayer(playerId);
    this.systems.translocator.removePlayer(playerId);
    this.options.decoySystem.clearPlayer(playerId);
    this.systems.tunnel.removePlayer(playerId);
  }

  /** Zieht eine geänderte committed/live Auswahl nach und klemmt laufende Ressourcen an neue Maxima. */
  reconcilePlayerLoadout(playerId: string, selection?: LoadoutSelection): boolean {
    const changed = this.systems.loadout.syncSelectedLoadout(playerId, selection);
    if (changed) {
      this.systems.rocketMagazine?.cancel(playerId);
      this.systems.ultimateBehavior.resetPlayer(playerId);
      this.systems.ak47Behavior?.resetPlayer(playerId);
      this.systems.negevBehavior.resetPlayer(playerId);
      this.systems.sustainedWeaponBehavior.resetPlayer(playerId);
      this.systems.weaponReaction.resetPlayer(playerId);
      this.systems.molotovUpgrade?.removePlayer(playerId);
      this.shieldBuffPort?.resetPlayer(playerId);
    }
    this.systems.utilityAction.syncEquippedUtility(playerId);
    this.systems.resource.reconcilePlayerLimits(playerId);
    return changed;
  }

  /**
   * Synct die Coop-Build-Modifikatoren aller Spieler und materialisiert/entfernt die Item-Runtime
   * genau für die Spieler mit tatsächlich geänderter Build.
   */
  reconcilePlayerBuildModifiers(
    builds: ReadonlyMap<string, Pick<LoadoutCommitSnapshot, 'coopDefenseClassId' | 'coopDefenseProfile' | 'equippedItems'> | null>,
    nowMs: number,
  ): void {
    const changedPlayerIds = this.systems.playerModifier.syncPlayers(builds);
    for (const playerId of changedPlayerIds) {
      this.systems.rocketMagazine?.cancel(playerId);
      const snapshot = builds.get(playerId) ?? null;
      const wantsItemRuntime = Boolean(snapshot?.coopDefenseProfile)
        || (snapshot?.equippedItems?.length ?? 0) > 0;
      if (wantsItemRuntime) {
        if (this.options.playerManager.hasPlayer(playerId)) this.systems.itemRuntime.initPlayer(playerId, nowMs);
      } else {
        this.systems.itemRuntime.removePlayer(playerId);
      }
    }
  }

